import os
import json
import re
from pathlib import Path

session_dir = os.environ.get('RLM_SESSION_DIR', '')
if session_dir:
    session_path = f"{session_dir}/../../sessions/{os.path.basename(session_dir)}.jsonl"
    if os.path.exists(session_path):
        with open(session_path, 'r') as f:
            content = f.read()

        # Find all demo pairs and test input
        task_id = "task-17ce086d"
        grids = {}

        # Pattern to match: "Demo pair N input (WxH):" or "Test input (WxH):" or "Output"
        lines = content.split('\n')
        current_grid = {}
        in_grid = False

        for line in lines:
            if task_id in line:
                current = line
            elif ":" in line:
                if current_grid:
                    grids[current] = "\n".join(current.split('\n')[:-1])
                current = line
            else:
                current = current + "\n" + line

        # Final entry
        if current_grid and ':' in current:
            name, val = current.split(':', 1)
            val = val.strip()
            if name == 'Output':
                current_grid['output'] = [[int(x) for x in row.split()] for row in val.split('\n') if row.strip()]
            else:
                current_grid['input'] = [[int(x) for x in row.split()] for row in val.split('\n') if row.strip()]

        if current_grid and current_grid.get('input') and current_grid.get('output'):
            grids[current] = (current_grid['input'], current_grid['output'])

        print(f"Found grids: {list(grids.keys())}")
    else:
        print(f"No session log found at {session_path}")
else:
    print("No session directory found")

